=head2 Google::Cloud::Networkmanagement::V1::Trace::GoogleServiceInfo

For display only. Details of a Google Service sending packets to a
VPC network. Although the source IP might be a publicly routable address,
some Google Services use special routes within Google production
infrastructure to reach Compute Engine Instances.
https://cloud.google.com/vpc/docs/routes#special_return_paths

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->source_ip() >> / C<< $msg->source_ip($value) >>

Type: C<String>

Source IP address.

=item * C<< $msg->google_service_type() >> / C<< $msg->google_service_type($value) >>

Type: C<Enum> (L<Google::Cloud::Networkmanagement::V1::GoogleServiceInfo::GoogleServiceType>)

Recognized type of a Google Service.

=back

=head3 Enum: GoogleServiceInfo::GoogleServiceType

=over 4

=item * C<GOOGLE_SERVICE_TYPE_UNSPECIFIED> => C<0>

=item * C<IAP> => C<1>

=item * C<GFE_PROXY_OR_HEALTH_CHECK_PROBER> => C<2>

=item * C<CLOUD_DNS> => C<3>

=item * C<GOOGLE_API> => C<4>

=item * C<GOOGLE_API_PSC> => C<5>

=item * C<GOOGLE_API_VPC_SC> => C<6>

=item * C<SERVERLESS_VPC_ACCESS> => C<7>

=back

=head2 Google::Cloud::Networkmanagement::V1::Trace::ForwardingRuleInfo

For display only. Metadata associated with a Compute Engine forwarding rule.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

Name of the forwarding rule.

=item * C<< $msg->uri() >> / C<< $msg->uri($value) >>

Type: C<String>

URI of the forwarding rule in format
"projects/{project}/global/forwardingRules/{forwarding_rule}" (global) or
"projects/{project}/regions/{region}/forwardingRules/{forwarding_rule}"
(regional).

=item * C<< $msg->matched_protocol() >> / C<< $msg->matched_protocol($value) >>

Type: C<String>

Protocol defined in the forwarding rule that matches the packet.

=item * C<< $msg->matched_port_range() >> / C<< $msg->matched_port_range($value) >>

Type: C<String>

Port range defined in the forwarding rule that matches the packet.

=item * C<< $msg->vip() >> / C<< $msg->vip($value) >>

Type: C<String>

VIP of the forwarding rule.

=item * C<< $msg->target() >> / C<< $msg->target($value) >>

Type: C<String>

Target type of the forwarding rule.

=item * C<< $msg->network_uri() >> / C<< $msg->network_uri($value) >>

Type: C<String>

URI of a VPC network where the forwarding rule is located in format
"projects/{project}/global/networks/{network}".

=item * C<< $msg->region() >> / C<< $msg->region($value) >>

Type: C<String>

Region of the forwarding rule. Set only for regional forwarding rules.

=item * C<< $msg->load_balancer_name() >> / C<< $msg->load_balancer_name($value) >>

Type: C<String>

Name of the load balancer the forwarding rule belongs to. Empty for
forwarding rules not related to load balancers (like PSC forwarding rules).

=item * C<< $msg->psc_service_attachment_uri() >> / C<< $msg->psc_service_attachment_uri($value) >>

Type: C<String>

URI of the PSC service attachment this forwarding rule targets (if
applicable) in format
"projects/{project}/regions/{region}/serviceAttachments/{service_attachment}".

=item * C<< $msg->psc_google_api_target() >> / C<< $msg->psc_google_api_target($value) >>

Type: C<String>

PSC Google API target this forwarding rule targets (if applicable).

=back

